      "import matplotlib.pyplot as plt\n\ncategories = [\"Food\", \"Cafe\", \"Transport\"]\namounts = [35500, 9500, 6000]\nplt.figure(figsize=(6, 4))\nplt.bar(categories, amounts)\nplt.title(\"Spending by category\")\nplt.xlabel(\"Category\")\nplt.ylabel(\"Amount (KRW)\")\nplt.ylim(bottom=0)\nplt.tight_layout()\nplt.show()\nprint(\"합계(원):\", sum(amounts))",
      "import matplotlib.pyplot as plt\n\ncategories = [\"Food\", \"Cafe\", \"Transport\"]\namounts = [35500, 9500, 6000]\nplt.figure(figsize=(6, 4))\nplt.bar(categories, amounts, color=\"#357566\")\nplt.title(\"Spending by category\")\nplt.xlabel(\"Category\")\nplt.ylabel(\"Amount (KRW)\")\nplt.ylim(bottom=0)\nplt.tight_layout()\nplt.show()\nprint(\"합계(원):\", sum(amounts))",
