      "import matplotlib.pyplot as plt\n\ndays = [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\"]\nminutes = [20, 35, 25, 40, 30]\nplt.figure(figsize=(6, 4))\nplt.plot(days, minutes, marker=\"o\")\nplt.title(\"Study time\")\nplt.xlabel(\"Day\")\nplt.ylabel(\"Minutes\")\nplt.ylim(bottom=0)\nplt.axhline(30, color=\"gray\", linestyle=\"--\")\nplt.tight_layout()\nplt.show()\nprint(\"변화(분):\", minutes[-1] - minutes[0])",
