    "solution": "import pandas as pd\nimport matplotlib.pyplot as plt\n\ndf = pd.read_csv(\"spending_raw.csv\")\nunique = df.drop_duplicates().copy()\nunique[\"amount\"] = pd.to_numeric(unique[\"amount\"], errors=\"coerce\")\nclean = unique.dropna(subset=[\"amount\"]).copy()\nsummary = clean.groupby(\"category\", as_index=False)[\"amount\"].sum()\nsummary = summary.sort_values(\"amount\", ascending=False)\nsummary[\"amount_k\"] = summary[\"amount\"] / 1000\nplt.figure(figsize=(6, 4))\nplt.bar(summary[\"category\"], summary[\"amount_k\"])\nplt.title(\"Known spending by category\")\nplt.xlabel(\"Category\")\nplt.ylabel(\"Amount (thousand KRW)\")\nplt.ylim(bottom=0)\nplt.tight_layout()\nplt.show()\nprint(\"추가 중복:\", len(df) - len(unique))\nprint(\"금액 미확인:\", len(unique) - len(clean))\nprint(\"확인된 합계(천 원):\", summary[\"amount_k\"].sum())",
