      "import pandas as pd\n\ndf = pd.read_csv(\"study_project.csv\")\nunique = df.drop_duplicates().copy()\nunique[\"minutes\"] = pd.to_numeric(unique[\"minutes\"], errors=\"coerce\")\nclean = unique.dropna(subset=[\"minutes\"]).copy()\nprint(\"원본 행:\", len(df))\nprint(\"복사본 제거 후:\", len(unique))\nprint(\"시간 미확인:\", unique[\"minutes\"].isna().sum())\nprint(\"분석 세션:\", len(clean))",
      "import pandas as pd\n\ndf = pd.read_csv(\"study_project.csv\")\nunique = df.drop_duplicates().copy()\nunique[\"minutes\"] = pd.to_numeric(unique[\"minutes\"], errors=\"coerce\")\nclean = unique.dropna(subset=[\"minutes\"]).copy()\nunknown = unique[unique[\"minutes\"].isna()]\nprint(unknown[[\"session_id\", \"week\", \"topic\"]])\nprint(\"시간 최솟값:\", clean[\"minutes\"].min())\nprint(\"시간 최댓값:\", clean[\"minutes\"].max())",
