      "import pandas as pd\nimport matplotlib.pyplot as plt\n\ndf = pd.read_csv(\"study_project.csv\")\nunique = df.drop_duplicates().copy()\nunique[\"minutes\"] = pd.to_numeric(unique[\"minutes\"], errors=\"coerce\")\nclean = unique.dropna(subset=[\"minutes\"]).copy()\nsummary = clean.groupby(\"week\", as_index=False)[\"minutes\"].sum()\nplt.figure(figsize=(6, 4))\nplt.bar(summary[\"week\"], summary[\"minutes\"])\nplt.xticks([1, 2], [\"Week 1\", \"Week 2\"])\nplt.title(\"Known study time by week\")\nplt.xlabel(\"Project week\")\nplt.ylabel(\"Total minutes\")\nplt.ylim(bottom=0)\nplt.tight_layout()\nplt.show()\nprint(\"주차별 총시간(분):\", summary[\"minutes\"].tolist())",
