    "solution": "import pandas as pd\nimport matplotlib.pyplot as plt\n\ndf = pd.read_csv(\"study_project.csv\")\nunique = df.drop_duplicates().copy()\nunique[\"minutes\"] = pd.to_numeric(unique[\"minutes\"], errors=\"coerce\")\nclean = unique.dropna(subset=[\"minutes\"]).copy()\nsummary = clean.groupby(\"topic\", as_index=False)[\"minutes\"].sum()\nsummary = summary.sort_values(\"minutes\", ascending=False)\nplt.figure(figsize=(6, 4))\nplt.barh(summary[\"topic\"], summary[\"minutes\"])\nplt.title(\"Known study time by topic\")\nplt.xlabel(\"Total minutes\")\nplt.ylabel(\"Topic\")\nplt.xlim(left=0)\nplt.tight_layout()\nplt.show()\nprint(summary)",
