    "solution": "import pandas as pd\nimport matplotlib.pyplot as plt\n\ndf = pd.read_csv(\"study_project.csv\")\nunique = df.drop_duplicates().copy()\nunique[\"minutes\"] = pd.to_numeric(unique[\"minutes\"], errors=\"coerce\")\nclean = unique.dropna(subset=[\"minutes\"]).copy()\npython_only = clean[clean[\"topic\"] == \"Python\"]\nsummary = python_only.groupby(\"week\")[\"minutes\"].agg([\"count\", \"mean\"])\nprint(\"대상: 시간이 확인된 Python 세션\")\nprint(summary.round(1))\nprint(\"한계: 시간 미확인 Python 세션 1건 제외. 실력 향상은 알 수 없음.\")\nplt.figure(figsize=(6, 4))\nplt.bar(summary.index, summary[\"mean\"])\nplt.xticks([1, 2], [\"Week 1\", \"Week 2\"])\nplt.title(\"Mean time of known Python sessions\")\nplt.xlabel(\"Project week\")\nplt.ylabel(\"Mean minutes per session\")\nplt.ylim(bottom=0)\nplt.tight_layout()\nplt.show()",
